CREATE   PROCEDURE [synapse_ce].[usp_Insert_rics_surveyresponse]
AS
BEGIN

;WITH cte AS
	(
		SELECT 
			[Id],
			[SinkCreatedOn],
			[SinkModifiedOn],
			[statecode],
			[statuscode],
			[rics_status],
			[rics_returnee],
			[rics_returnee_entitytype],
			[owningteam],
			[owningteam_entitytype],
			[owninguser],
			[owninguser_entitytype],
			[createdonbehalfby],
			[createdonbehalfby_entitytype],
			[owningbusinessunit],
			[owningbusinessunit_entitytype],
			[modifiedby],
			[modifiedby_entitytype],
			[createdby],
			[createdby_entitytype],
			[rics_survey],
			[rics_survey_entitytype],
			[modifiedonbehalfby],
			[modifiedonbehalfby_entitytype],
			[rics_surveyrequest],
			[rics_surveyrequest_entitytype],
			[ownerid],
			[ownerid_entitytype],
			[createdonbehalfbyyominame],
			[rics_totalanswersrequired],
			[createdbyname],
			[rics_responsescore],
			[owneridname],
			[rics_responsescore_date],
			[rics_surveyrequestname],
			[rics_name],
			[rics_surveyresponseid],
			[importsequencenumber],
			[rics_returneename],
			[utcconversiontimezonecode],
			[createdbyyominame],
			[modifiedbyname],
			[versionnumber],
			[modifiedbyyominame],
			[timezoneruleversionnumber],
			[owneridtype],
			[rics_returneeyominame],
			[rics_surveyname],
			[owneridyominame],
			[modifiedon],
			[rics_responsescore_state],
			[modifiedonbehalfbyyominame],
			[rics_totalquestions],
			[createdon],
			[rics_datecompleted],
			[modifiedonbehalfbyname],
			[rics_datestarted],
			[createdonbehalfbyname],
			[rics_totalanswersprovided],
			[overriddencreatedon],
			[owningbusinessunitname],
			ROW_NUMBER() OVER(PARTITION BY ID ORDER BY ID DESC) AS RowNo
		FROM [staging_ce].[rics_surveyresponse] stg
	)


	INSERT INTO [synapse_ce].[rics_surveyresponse]
	(
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[rics_datecompleted],
		[rics_datestarted],
		[rics_name],
		[rics_responsescore],
		[rics_responsescore_date],
		[rics_responsescore_state],
		[rics_returnee],
		[rics_returnee_entitytype],
		[rics_returneename],
		[rics_returneeyominame],
		[rics_status],
		[rics_survey],
		[rics_survey_entitytype],
		[rics_surveyname],
		[rics_surveyrequest],
		[rics_surveyrequest_entitytype],
		[rics_surveyrequestname],
		[rics_surveyresponseid],
		[rics_totalanswersprovided],
		[rics_totalanswersrequired],
		[rics_totalquestions],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[rics_datecompleted],
		stg.[rics_datestarted],
		stg.[rics_name],
		stg.[rics_responsescore],
		stg.[rics_responsescore_date],
		stg.[rics_responsescore_state],
		stg.[rics_returnee],
		stg.[rics_returnee_entitytype],
		stg.[rics_returneename],
		stg.[rics_returneeyominame],
		stg.[rics_status],
		stg.[rics_survey],
		stg.[rics_survey_entitytype],
		stg.[rics_surveyname],
		stg.[rics_surveyrequest],
		stg.[rics_surveyrequest_entitytype],
		stg.[rics_surveyrequestname],
		stg.[rics_surveyresponseid],
		stg.[rics_totalanswersprovided],
		stg.[rics_totalanswersrequired],
		stg.[rics_totalquestions],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM cte stg--[staging_ce].[rics_surveyresponse] stg
		LEFT JOIN [synapse_ce].[rics_surveyresponse] tgt
			ON tgt.[id] = stg.[id]
	WHERE stg.[RowNo] = 1
		AND tgt.[id] IS NULL

END
